135	///   spaces so subprocess output sits visually under the caller's own
136	///   `info!` line in `-v` mode.
137	/// - **stdout at `debug!`**: callers usually consume stdout as data
138	///   (bookmark lists, commit IDs, etc.), and `info!` would flood the user
139	///   with machine-readable output they didn't ask for.
140	/// - **Failures propagate as `Err`** carrying the stderr; the caller's
141	///   error handler (`main::run_command`) surfaces it at `error!`.
142	pub fn run(cmd: &str, args: &[&str], cwd: &Path) -> Result<String, Box<dyn std::error::Error>> {
143	    let args_str = args.join(" ");
144	    debug!("$ {cmd} {args_str}");
145	    trace!("cwd: {}", cwd.display());
146	    let output = std::process::Command::new(cmd)
147	        .args(args)
148	        .current_dir(cwd)
149	        .output()
150	        .map_err(|e| format!("failed to run {cmd}: {e}"))?;
151	    let stdout = String::from_utf8_lossy(&output.stdout).trim().to_string();
152	    let stderr = String::from_utf8_lossy(&output.stderr).trim().to_string();
153	    if !stdout.is_empty() {
154	        debug!("{stdout}");
155	    }
156	    if !output.status.success() {
157	        return Err(format!("{cmd} {args_str} failed: {stderr}").into());
158	    }
159	    if !stderr.is_empty() {
160	        debug!("{stderr}");
161	    }
162	    Ok(stdout)
163	}
