4	//! The format: a config file is a markdown document whose `toml`
5	//! fences, concatenated in document order, form the TOML the loader
6	//! parses. Prose between fences is documentation (doc one-liners,
7	//! reference links) and never reaches the parser. One rule falls
8	//! out for authors: a `[table]` header captures every key after it
9	//! until the next header, so a table's keys must stay in its
10	//! stretch of the document.
11	//!
12	//! The filter itself is [`crate::md_fence`], which build.rs shares
13	//! to parse the `vc-config.md` schema prototype in the same format.
14	//!
15	//! `.vc-config.toml` remains a valid carrier through the family's
16	//! migration window; a side holding both carriers is an error.
17	
18	use std::collections::HashMap;
19	use std::path::{Path, PathBuf};
20	
21	use crate::desc_helpers::VC_CONFIG_FILE;
22	use crate::md_fence::md_to_toml;
23	use crate::toml_simple;
24	
25	/// The markdown instance-config filename (the toml carrier's name
26	/// is [`VC_CONFIG_FILE`]).
27	pub const VC_CONFIG_MD: &str = ".vc-config.md";
28	
29	/// Resolve which instance-config file `dir` holds.
30	///
31	/// `Ok(None)` when neither carrier exists. Holding both is an
32	/// error: two files that can disagree are no longer a config.
33	pub fn vc_config_path(dir: &Path) -> Result<Option<PathBuf>, String> {
34	    let md = dir.join(VC_CONFIG_MD);
35	    let toml = dir.join(VC_CONFIG_FILE);
36	    match (md.exists(), toml.exists()) {
37	        (true, true) => Err(format!(
38	            "{}: both {VC_CONFIG_MD} and {VC_CONFIG_FILE} exist: keep one \
39	             ({VC_CONFIG_MD} is the current carrier); nothing was changed",
40	            dir.display()
41	        )),
42	        (true, false) => Ok(Some(md)),
43	        (false, true) => Ok(Some(toml)),
44	        (false, false) => Ok(None),
45	    }
46	}
47	
48	/// Load one config file, whatever its carrier: a `.md` path runs
49	/// through [`md_to_toml`] first, anything else parses as plain
50	/// TOML.
51	pub fn load_file(path: &Path) -> Result<HashMap<String, String>, Box<dyn std::error::Error>> {
52	    if path.extension().is_some_and(|e| e == "md") {
53	        let content = std::fs::read_to_string(path)
54	            .map_err(|e| format!("cannot read '{}': {e}", path.display()))?;
55	        let toml = md_to_toml(&content).map_err(|e| format!("{}: {e}", path.display()))?;
56	        Ok(toml_simple::toml_parse(&toml))
57	    } else {
58	        toml_simple::toml_load(path)
59	    }
60	}
61	
62	/// A loaded instance config: the file it came from (for messages)
63	/// and its flat key map.
64	pub struct VcConfig {
65	    pub path: PathBuf,
66	    pub map: HashMap<String, String>,
67	}
68	
69	/// Resolve and load `dir`'s instance config.
70	///
71	/// `Ok(None)` when the directory has no config file; an error is a
72	/// real problem (both carriers present, unreadable file, a bad
73	/// fence), never a plain miss.
74	pub fn load(dir: &Path) -> Result<Option<VcConfig>, Box<dyn std::error::Error>> {
75	    let Some(path) = vc_config_path(dir)? else {
76	        return Ok(None);
77	    };
78	    let map = load_file(&path)?;
79	    Ok(Some(VcConfig { path, map }))
80	}
